{
  "title": "Competitive brief and landing page for a self-hosted AI agent platform",
  "background": "The owner needs a one-page, sourced competitive brief on self-hosted AI agent platforms, followed by a landing page draft grounded in that research. No product capabilities or target audience were supplied. The team should state working assumptions and clearly flag proposed claims that require product validation.",
  "outcome": "A concise competitive brief comparing relevant platforms and identifying a defensible positioning opportunity, plus a landing page copy draft that translates those findings into clear messaging.",
  "doneDefinition": "The one-page brief includes dated, linked sources and a consistent comparison of relevant self-hosted AI agent platforms. The landing page draft includes a headline, value proposition, benefits, differentiation, and call to action. Competitive claims trace to the brief; unverified product claims and assumptions are explicitly marked.",
  "questions": [],
  "department": null,
  "tasks": [
    {
      "title": "Research and write the one-page competitive brief",
      "brief": "Research 4–5 relevant self-hosted AI agent platforms using current primary sources. Define self-hosted for this comparison and distinguish agent platforms from adjacent workflow tools. Use a working audience of technical teams evaluating deployment under their own control. Compare deployment options, licensing and commercial restrictions, agent capabilities, integrations, operational demands, and publicly documented pricing. Distinguish unavailable information from absent features. Write a one-page brief of at most 650 words, including a compact comparison, key tradeoffs, and a positioning opportunity. Include linked sources and an as-of date. Put additional evidence and caveats in a separate source ledger. Treat any proposed offering's capabilities as unknown.",
      "assignee": "ricky",
      "workKind": "research",
      "outputs": [
        "competitive-brief.md",
        "competitive-sources.md"
      ],
      "criteria": [
        {
          "text": "Compares 4–5 relevant platforms using consistent dimensions and explains inclusion and the meaning of self-hosted.",
          "weight": 25
        },
        {
          "text": "Material factual claims have traceable primary sources and an as-of date; licensing, pricing, deployment limitations, and unknowns are represented accurately.",
          "weight": 35
        },
        {
          "text": "The brief is at most 650 words and presents useful tradeoffs and a positioning opportunity without asserting unverified product capabilities.",
          "weight": 25
        },
        {
          "text": "The source ledger records supporting links, access dates, and caveats so the brief can be checked and refreshed independently.",
          "weight": 15
        }
      ],
      "dependsOn": []
    },
    {
      "title": "Draft landing page copy grounded in the competitive brief",
      "brief": "Use competitive-brief.md and competitive-sources.md to write a landing page copy draft for a proposed self-hosted AI agent platform. Carry forward the brief's working audience and positioning. Deliver copy in reading order: hero headline and subheadline, primary call to action, customer problem, three core benefits, differentiation, a short how-it-works section, and closing call to action. Use a neutral product-name placeholder. Do not invent features, benchmarks, testimonials, customer logos, security assurances, or availability. Mark proposed capabilities and claims requiring owner validation. Add a compact claim map linking competitive and market claims to the brief's evidence, and list assumptions and decisions needed before publication. The deliverable is a copy draft; no implementation or publication is required.",
      "assignee": "brody",
      "workKind": "build",
      "outputs": [
        "landing-page-draft.md",
        "landing-page-claim-map.md"
      ],
      "criteria": [
        {
          "text": "Includes all requested page sections in a coherent reading order with a clear audience, value proposition, and consistent call to action.",
          "weight": 30
        },
        {
          "text": "Positioning and differentiation reflect the brief's findings, and every factual competitive or market claim traces to supporting evidence.",
          "weight": 30
        },
        {
          "text": "Unverified product capabilities and assumptions are clearly marked, with no fabricated proof, performance promises, or availability claims.",
          "weight": 25
        },
        {
          "text": "Copy is concise and suitable for a landing page; the supporting claim map identifies concrete decisions required before publication.",
          "weight": 15
        }
      ],
      "dependsOn": [
        0
      ]
    }
  ]
}
